using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.IO;using System.Web.Script.Serialization;using System.Windows.Forms;
namespace SlopStudio {
 public sealed class SamplerEditor:Form {
  private SamplerView _view;private StudioChoice _preset;private SamplerSettings _sampler;private bool _recording;private Func<bool,string> _record;private Action<SamplerSettings> _update;
  public SamplerEditor(string preset,SamplerSettings settings,Action<string> change,Action<SamplerSettings> update,Func<string,string> import,Func<bool,string> record,Action<int,bool> preview){
   _sampler=settings.Copy();_record=record;_update=update;Text="Sampler";ClientSize=new Size(880,580);MinimumSize=new Size(700,460);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(35,38,43);ForeColor=Color.Gainsboro;Font=new Font("Segoe UI",9);
   var header=new Panel{Dock=DockStyle.Top,Height=58,Padding=new Padding(18,10,18,8)};
   header.Controls.Add(new Label{Text="Sampler",Dock=DockStyle.Left,Width=170,Font=new Font("Segoe UI",18,FontStyle.Bold),ForeColor=Color.FromArgb(218,228,237)});
   _preset=new StudioChoice{Dock=DockStyle.Right,Width=250};_preset.Items.AddRange(BuiltinSounds.Names);_preset.SelectedItem=preset;header.Controls.Add(_preset);
   _view=new SamplerView{Dock=DockStyle.Fill,Preview=preview};_view.SetBank(preset,_sampler);
   var controls=new FlowLayoutPanel{Dock=DockStyle.Top,Height=135,WrapContents=false,AutoScroll=true,Padding=new Padding(14,6,10,4),BackColor=CyberTheme.Surface};
   var open=new Button{Text="Import Sample…",AutoSize=true,Height=28};var rec=new Button{Text="Record Sample",AutoSize=true,Height=28};
   Action apply=delegate{_sampler.Validate();_update(_sampler.Copy());_view.SetBank(Convert.ToString(_preset.SelectedItem),_sampler);};
   open.Click+=delegate{using(var d=new OpenFileDialog{Filter="Audio files|*.wav;*.wave;*.aif;*.aiff;*.flac;*.mp3;*.ogg;*.m4a|All files|*.*"})if(d.ShowDialog(this)==DialogResult.OK)try{_sampler.SamplePath=import(d.FileName);apply();}catch(Exception ex){MessageBox.Show(this,ex.Message,UiText.Translate("Sample import failed"),MessageBoxButtons.OK,MessageBoxIcon.Error);}};
   rec.Click+=delegate{try{if(!_recording){_record(true);_recording=true;rec.Text=UiText.Translate("Stop Recording");}else{string file=_record(false);_recording=false;rec.Text=UiText.Translate("Record Sample");if(!String.IsNullOrEmpty(file)){_sampler.SamplePath=file;apply();}}}catch(Exception ex){_recording=false;rec.Text=UiText.Translate("Record Sample");MessageBox.Show(this,ex.Message,UiText.Translate("Recording failed"),MessageBoxButtons.OK,MessageBoxIcon.Error);}};
   var sampleTools=new FlowLayoutPanel{Width=205,Height=112,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(2,0,8,0)};
   sampleTools.Controls.Add(open);sampleTools.Controls.Add(rec);var rootPanel=new FlowLayoutPanel{Width=195,Height=30,WrapContents=false,Margin=Padding.Empty};rootPanel.Controls.Add(new Label{Text="Root",Width=75,Height=25,TextAlign=ContentAlignment.MiddleLeft});
   bool syncing=false;var syncControls=new List<Action>();
   var root=new NumericUpDown{Minimum=0,Maximum=127,Value=_sampler.RootNote,Width=66,AccessibleName="Sample root note"};root.ValueChanged+=delegate{if(syncing)return;try{_sampler.RootNote=(int)root.Value;apply();}catch(Exception ex){MessageBox.Show(this,ex.Message,UiText.Translate("Sampler"),MessageBoxButtons.OK,MessageBoxIcon.Error);}};rootPanel.Controls.Add(root);sampleTools.Controls.Add(rootPanel);controls.Controls.Add(sampleTools);
   Action<string,double,double,Func<double>,Action<double>> envelope=delegate(string label,double maximum,double current,Func<double> read,Action<double> changed){
    var group=new Panel{Width=105,Height=112,Margin=new Padding(3,0,3,0),BackColor=CyberTheme.Control};
    var title=new Label{Text=label,Dock=DockStyle.Top,Height=23,TextAlign=ContentAlignment.MiddleCenter};
    var knob=new EffectKnob{Dock=DockStyle.Fill,Parameter=new EffectParameter(label,label,"",0,maximum,current),Value=current,Exponential=maximum>1,AccessibleName="Sampler "+label,TabStop=true};
    var number=new NumericUpDown{Minimum=0,Maximum=(decimal)maximum,DecimalPlaces=3,Increment=.01m,Value=(decimal)Math.Max(0,Math.Min(maximum,current)),Dock=DockStyle.Bottom,Height=24,TextAlign=HorizontalAlignment.Center,AccessibleName="Sampler "+label+" value"};
    bool updating=false;Action<double> applyValue=delegate(double v){_sampler.Validate();changed(v);_sampler.Validate();_update(_sampler.Copy());};
    number.ValueChanged+=delegate{if(updating||syncing)return;try{updating=true;knob.Value=(double)number.Value;knob.Invalidate();applyValue(knob.Value);}finally{updating=false;}};
    knob.Changed+=delegate(double v){if(updating||syncing)return;try{updating=true;number.Value=Math.Max(number.Minimum,Math.Min(number.Maximum,Math.Round((decimal)v,3)));knob.Value=(double)number.Value;applyValue(knob.Value);}finally{updating=false;}};
    syncControls.Add(delegate{double v=read();number.Value=Math.Max(number.Minimum,Math.Min(number.Maximum,(decimal)v));knob.Value=v;knob.Invalidate();});
    group.Controls.Add(knob);group.Controls.Add(title);group.Controls.Add(number);controls.Controls.Add(group);
   };
   envelope("Attack (s)",30,_sampler.Attack,()=>_sampler.Attack,v=>_sampler.Attack=v);envelope("Decay (s)",30,_sampler.Decay,()=>_sampler.Decay,v=>_sampler.Decay=v);envelope("Sustain",1,_sampler.Sustain,()=>_sampler.Sustain,v=>_sampler.Sustain=v);envelope("Release (s)",30,_sampler.Release,()=>_sampler.Release,v=>_sampler.Release=v);
   _preset.SelectedIndexChanged+=delegate{string name=Convert.ToString(_preset.SelectedItem);_view.Release();_sampler.SamplePath=null;change(name);apply();};
   var footer=new Label{Dock=DockStyle.Bottom,Height=32,Text="PCM sample  ·  root note  ·  ADSR  ·  64 voices",TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(153,174,192)};
   var presets=new PresetToolbar("Built-in","Sampler",()=>new JavaScriptSerializer().Serialize(_sampler),state=>{
    var loaded=new JavaScriptSerializer().Deserialize<SamplerSettings>(state);if(loaded==null)throw new InvalidDataException("Invalid Sampler preset.");
    loaded.TrackId=_sampler.TrackId;loaded.Validate();if(!String.IsNullOrEmpty(loaded.SamplePath)&&!File.Exists(loaded.SamplePath))throw new FileNotFoundException("The sample referenced by this preset is unavailable.",loaded.SamplePath);
    _sampler=loaded;syncing=true;try{root.Value=_sampler.RootNote;foreach(var sync in syncControls)sync();}finally{syncing=false;}apply();
   });
   Controls.Add(_view);Controls.Add(controls);Controls.Add(presets);Controls.Add(header);Controls.Add(footer);Shown+=delegate{UiText.Apply(this);presets.CaptureReference();};FormClosed+=delegate{_view.Release();if(_recording){_recording=false;try{string file=_record(false);if(!String.IsNullOrEmpty(file)){_sampler.SamplePath=file;_update(_sampler.Copy());}}catch{}}};
  }
  private sealed class SamplerView:ScaledCanvas {
   private SamplerSample[] _bank;private string _warning;private int _sample,_note=-1;public Action<int,bool> Preview;public SamplerView(){DoubleBuffered=true;BackColor=Color.FromArgb(24,28,34);Font=new Font("Segoe UI",9);}
   public void SetBank(string preset,SamplerSettings settings){try{_bank=settings!=null&&!String.IsNullOrEmpty(settings.SamplePath)?SamplerBank.LoadFile(settings.SamplePath,settings.RootNote):SamplerBank.Load(preset);_warning=null;}catch(Exception ex){_bank=SamplerBank.Load(preset);_warning=ex.Message;}_sample=0;Invalidate();}
   private System.Collections.Generic.List<Tuple<int,Rectangle,bool>> Keys(){var result=new System.Collections.Generic.List<Tuple<int,Rectangle,bool>>();double width=(Width-44)/28.0;int white=0,y=Height-60;for(int pitch=36;pitch<84;pitch++){bool black=new[]{1,3,6,8,10}.Contains(pitch%12);if(!black){result.Add(Tuple.Create(pitch,new Rectangle(22+(int)Math.Round(white*width),y,Math.Max(1,(int)Math.Ceiling(width)-1),52),false));white++;}else result.Add(Tuple.Create(pitch,new Rectangle(22+(int)Math.Round(white*width-width*.32),y,Math.Max(2,(int)(width*.6)),32),true));}return result;}
   protected override void OnPaint(PaintEventArgs e){PreparePaint(e);var g=e.Graphics;g.Clear(BackColor);if(_bank==null)return;int w=Width,h=Height;var wave=new Rectangle(22,48,w-44,Math.Max(70,h-180));using(var pen=new Pen(Color.FromArgb(48,58,72))){g.DrawRectangle(pen,wave);g.DrawLine(pen,wave.X,wave.Top+wave.Height/2,wave.Right,wave.Top+wave.Height/2);}var sample=_bank[_sample];using(var pen=new Pen(Color.FromArgb(111,180,224))){for(int x=0;x<wave.Width;x++){int at=x*(sample.Pcm.Length-1)/wave.Width;float amp=Math.Abs(sample.Pcm[at])*wave.Height*.45f;g.DrawLine(pen,wave.X+x,wave.Y+wave.Height/2-amp,wave.X+x,wave.Y+wave.Height/2+amp);}}StudioDraw.Label(g,(_warning==null?"PCM  /  ":"Missing sample — fallback  /  ")+sample.Rate+" Hz  /  "+sample.Pcm.Length+" samples  /  "+UiText.Translate(sample.Loop?"Loop":"One shot"),Font,new Rectangle(22,17,w-44,25),Color.FromArgb(183,207,226),TextFormatFlags.VerticalCenter);int zonesY=wave.Bottom+18;for(int i=0;i<_bank.Length;i++){int x=22+i*(w-44)/_bank.Length;var rect=new Rectangle(x,zonesY,Math.Max(1,(w-44)/_bank.Length-2),30);using(var b=new SolidBrush(i==_sample?Color.FromArgb(58,111,150):Color.FromArgb(49,61,76)))g.FillRectangle(b,rect);StudioDraw.Label(g,UiText.Translate("Root")+" "+_bank[i].Root,Font,rect,Color.Gainsboro,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}foreach(var key in Keys().OrderBy(k=>k.Item3)){var rect=key.Item2;using(var b=new SolidBrush(key.Item1==_note?Color.FromArgb(96,170,213):key.Item3?Color.FromArgb(32,37,43):Color.FromArgb(190,196,201)))g.FillRectangle(b,rect);using(var p=new Pen(Color.FromArgb(17,23,28)))g.DrawRectangle(p,rect);if(key.Item1%12==0)StudioDraw.Label(g,"C"+(key.Item1/12-1),Font,new Rectangle(rect.X,rect.Bottom-18,rect.Width,16),Color.FromArgb(70,77,84),TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter);}}

   protected override void OnMouseDown(MouseEventArgs e){e=LogicalMouse(e);base.OnMouseDown(e);if(e.Button!=MouseButtons.Left||_bank==null)return;if(e.Y>=Height-60){Release();var hit=Keys().OrderByDescending(k=>k.Item3).FirstOrDefault(k=>k.Item2.Contains(e.Location));if(hit==null)return;_note=hit.Item1;if(Preview!=null)Preview(_note,true);Capture=true;}else{int zonesY=Math.Max(70,Height-180)+66;if(e.Y>=zonesY&&e.Y<zonesY+30)_sample=Math.Max(0,Math.Min(_bank.Length-1,(e.X-22)*_bank.Length/Math.Max(1,Width-44)));}Invalidate();}
   protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);Release();}
   public void Release(){if(_note>=0&&Preview!=null)Preview(_note,false);_note=-1;Capture=false;Invalidate();}
  }
 }
 public sealed partial class MainForm {
  private void OpenSampler(Track track){if(track==null||track.Type!=TrackType.Midi)return;AudioRecordingSession capture=null;string folder=String.IsNullOrEmpty(_projectPath)?Path.Combine(Path.GetDirectoryName(SettingsStore.DefaultPath),"Recordings"):Path.Combine(Path.GetDirectoryName(_projectPath),"Media");Func<bool,string> record=start=>{if(start){if(_recording)throw new InvalidOperationException("Stop project recording before recording a sample.");if(!_engine.DeviceRunning)_engine.OpenDevices();if(_engine.InputChannels<1)throw new InvalidOperationException("No audio input is available.");capture=new AudioRecordingSession(new[]{track},_project.Studio,folder,_settings.SampleRate,_engine.InputChannels);_engine.AudioInputReceived+=capture.Receive;return null;}if(capture==null)return null;var session=capture;capture=null;_engine.AudioInputReceived-=session.Receive;var takes=session.Finish();if(takes.Count==0)throw new InvalidOperationException("No audio was captured.");return takes[0].Path;};Action<SamplerSettings> update=value=>{if(IsDisposed||FindTrack(value.TrackId)==null)return;var state=_project.Studio.Copy();state.Samplers.RemoveAll(x=>x.TrackId==value.TrackId);state.Samplers.Add(value.Copy());CommitStudio("Edit Sampler",state);};var form=new SamplerEditor(track.Instrument,_project.Studio.Sampler(track.Id),name=>{if(SelectedTrack==null||SelectedTrack.Id!=track.Id)Select(track.Id,null);SelectPreset(name);},update,file=>MediaImport.Decode(file,folder),record,(pitch,on)=>{try{if(on&&!_engine.DeviceRunning)_engine.OpenDevices();_engine.SetMidiThruTrack(track.Id);_engine.InjectMidi(on?0x90:0x80,pitch,on?100:0);if(!on)_engine.SetMidiThruTrack(SelectedTrack!=null&&SelectedTrack.Type==TrackType.Midi?(Guid?)SelectedTrack.Id:null);}catch(Exception ex){ShowError("Sampler preview failed",ex);}});form.Show(this);}
 }
}
